effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////
    #define RED vec3(1.0,0.0,0.0)
    #define GREEN vec3(0.0,1.0,0.0)
    #define BLUE vec3(0.0,0.5,1.0)
    #define YELLOW vec3(1.0,1.0,0.0)
    #define WHITE vec3(1.0,1.0,1.0)
    #define PI 3.141592653
    vec2 rotatevec2(vec2 vec, float ang)
    {

        return vec2(vec.x * cos(ang) - vec.y * sin(ang),
                    vec.x * sin(ang) + vec.y * cos(ang));
    }
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

    vec2 umefx;
    // umefx = acScreenNorm; 
    umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    umefx.y*=acLayerSize.y/acLayerSize.x;

    umefx /= scale;
    umefx *= rot2m((0.0+angle)*0.0174533);
    umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.0,1.0)/500.0;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    umefx /= scaleVec;

    /////////////////////////

	vec4 fragColor;

        vec2 uv = umefx;

        float moBlurStrength = MBS / 0.01;
        float tangentStrength = TS;
        float texHeight = 256.0;

        float timeSpeed = TIMEAMP * 0.01;
        float time = iTime*timeSpeed;
        float timeB = iTime*timeSpeed-0.0002;

        ///// particles
        vec3 particles = vec3(0.0);
        vec2 p1, p2, t1, t2;
        vec2 p1B, p2B, t1B, t2B;

        for (float i = 0.0; i<1.0; i+=1.0/AMOUNT)
        {
            time += i*16.6516;
            timeB += i*16.6516;
            p1 = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((time/texHeight)/2.0)*2.0),fract(time))).xy-vec2(0.5);
            p2 = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((time/texHeight)/2.0)*2.0),fract(time+1.0/texHeight))).xy-vec2(0.5);
            t1 = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((time/texHeight)/2.0)*2.+1.0/texHeight),fract(time))).xy-vec2(0.5);
            t2 = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((time/texHeight)/2.0)*2.+1.0/texHeight),fract(time+1.0/texHeight))).xy-vec2(0.5);

            p1B = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((timeB/texHeight)/2.0)*2.0),fract(timeB))).xy-vec2(0.5);
            p2B = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((timeB/texHeight)/2.0)*2.0),fract(timeB+1.0/texHeight))).xy-vec2(0.5);
            t1B = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((timeB/texHeight)/2.0)*2.+1.0/texHeight),fract(timeB))).xy-vec2(0.5);
            t2B = texture2DCv(noisexx.texture,vec2(i,0.0)+vec2(fract(floor((timeB/texHeight)/2.0)*2.+1.0/texHeight),fract(timeB+1.0/texHeight))).xy-vec2(0.5);

            t1 = normalize(p1-t1)*tangentStrength;
            t2 = normalize(p2-t2)*tangentStrength;

            t1B = normalize(p1B-t1B)*tangentStrength;
            t2B = normalize(p2B-t2B)*tangentStrength;

            vec2 p3, p4;
            vec2 p3B, p4B;
            if (mod(floor(time*texHeight),2.0)==1.0)
            {
                p3 = mix(p1,p1-t1,fract(time*texHeight));
                p4 = mix(p2-t2,p2,fract(time*texHeight));
            }
            else
            {
                p3 = mix(p1,p1+t1,fract(time*texHeight));
                p4 = mix(p2+t2,p2,fract(time*texHeight));
            }
            if (mod(floor(timeB*texHeight),2.0)==1.0)
            {
                p3B = mix(p1B,p1B-t1B,fract(timeB*texHeight));
                p4B = mix(p2B-t2B,p2B,fract(timeB*texHeight));
            }
            else
            {
                p3B = mix(p1B,p1B+t1B,fract(timeB*texHeight));
                p4B = mix(p2B+t2B,p2B,fract(timeB*texHeight));
            }

            vec2 finPos = uv+mix(p3,p4,smoothstep(0.0,1.0,fract(time*texHeight)));
            vec2 finPos2 = uv+mix(p3B,p4B,smoothstep(0.0,1.0,fract((timeB)*texHeight)));

            vec2 finSpeed = finPos2-finPos;

            finPos += (texture2DCv(noisexx.texture, vec2(i)).xy-vec2(0.5))*vec2(2.6,1.0);

            float pSize = 1.0+3.0*(texture2DCv(noisexx.texture,vec2(0.0,i)).x);

            particles += 0.08*(YELLOW)*vec3(0.18/(pSize*length(finPos)));

            finPos = rotatevec2(finPos,atan(finSpeed.x/finSpeed.y));
            finPos.y *= 1.0-clamp(length(abs(finSpeed))*moBlurStrength*timeSpeed,0.0,0.8);

            finPos.y *= 1.0-clamp(length(abs(finSpeed))*moBlurStrength*pSize*timeSpeed,0.0,0.8);

            particles += (WHITE)*vec3(smoothstep(0.03,0.004,pSize*length(finPos)));
            //\\\ END particles
        }
        fragColor = vec4(particles,1.0);

	    vec4 factor = mix(texColorX,fragColor,1.0);
	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
	    // if(GRADMAP) { 
	    factor = mix(texColorX,gradmap,1.0); // }

	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

    vec4 resultfinal;
      if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.0)*(1.0-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }
      else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
